int x25_negotiate_facilities(struct sk_buff *skb, struct sock *sk, struct x25_facilities *new, struct x25_dte_facilities *dte) {
    struct x25_facility *facility;
    int len = 0;
    u8 *data;

    memset(new, 0, sizeof(*new));
    memset(dte, 0, sizeof(*dte));

    data = skb->data;
    while (len < skb->len) {
        facility = (struct x25_facility *) (data + len);

        switch (facility->type) {
            case X25_FAC_THROUGHPUT:
                new->throughput = ntohs(facility->value);
                break;
            case X25_FAC_PACKET_SIZE:
                new->packet_size = ntohs(facility->value);
                break;
            case X25_FAC_WINDOW_SIZE:
                new->window_size = ntohs(facility->value);
                break;
            case X25_FAC_REVERSE_CHARGING:
                dte->reverse_charging = facility->value;
                break;
            default:
                break;
        }

        len += facility->length;
    }

    if (new->throughput > X25_MAX_THROUGHPUT)
        new->throughput = X25_MAX_THROUGHPUT;

    if (new->packet_size > X25_MAX_PACKET_SIZE)
        new->packet_size = X25_MAX_PACKET_SIZE;

    if (new->window_size > X25_MAX_WINDOW_SIZE)
        new->window_size = X25_MAX_WINDOW_SIZE;

    if (dte->reverse_charging)
        new->reverse_charging = 1;

    return len;
}

int x25_negotiate_facilities(struct sk_buff *skb, struct sock *sk, struct x25_facilities *new, struct x25_dte_facilities *dte)
{
    struct x25_facilities *local;
    unsigned char *ptr;
    int len = 0;
    int reverse_charging = 0;

    local = kmalloc(sizeof(*local), GFP_ATOMIC);
    if (!local)
        return -ENOMEM;

    memset(local, 0, sizeof(*local));

    ptr = skb->data;
    if (skb->len < 1)
        goto out;

    /* Parse facilities */
    if (*ptr & 0x80) {
        if (skb->len < 5)
            goto out;

        local->throughput = *(ptr + 1);
        local->window_size = *(ptr + 2);
        local->packet_size = *(ptr + 3);
        local->reverse_charging = *(ptr + 4) & 0x01;
        len = 5;
        ptr += 5;
    }

    if (*ptr & 0x08) {
        if (skb->len < len + 5)
            goto out;

        local->dte_throughput = *(ptr + 1);
        local->dte_window_size = *(ptr + 2);
        local->dte_packet_size = *(ptr + 3);
        local->dte_reverse_charging = *(ptr + 4) & 0x01;
        len += 5;
        ptr += 5;
    }

    if (local->reverse_charging) {
        reverse_charging = 1;
    }

    /* Negotiate throughput */
    if (local->throughput > 0 && local->throughput < X25_DEFAULT_THROUGHPUT)
        new->throughput = local->throughput;
    else
        new->throughput = X25_DEFAULT_THROUGHPUT;

    /* Negotiate window size */
    if (local->window_size > 0 && local->window_size < X25_DEFAULT_WINDOW_SIZE)
        new->window_size = local->window_size;
    else
        new->window_size = X25_DEFAULT_WINDOW_SIZE;

    /* Negotiate packet size */
    if (local->packet_size > 0 && local->packet_size < X25_DEFAULT_PACKET_SIZE)
        new->packet_size = local->packet_size;
    else
        new->packet_size = X25_DEFAULT_PACKET_SIZE;

    /* Copy DTE facilities if present */
    if (local->dte_throughput > 0) {
        dte->throughput = local->dte_throughput;
        dte->window_size = local->dte_window_size;
        dte->packet_size = local->dte_packet_size;
    }

    if (reverse_charging) {
        new->reverse_charging = 1;
        printk(KERN_DEBUG "X.25: Reverse charging requested\n");
    }

out:
    kfree(local);
    return len ? len : -EINVAL;
}

int x25_negotiate_facilities(struct sk_buff *skb, struct sock *sk,
                             struct x25_facilities *new,
                             struct x25_dte_facilities *dte)
{
    struct x25_facilities incoming;
    int len = 0;
    u8 *data = skb->data;

    /* Initialize incoming and negotiated facilities */
    memset(&incoming, 0, sizeof(incoming));
    memset(new, 0, sizeof(*new));
    memset(dte, 0, sizeof(*dte));

    /* Parse incoming facilities from the socket buffer */
    if (skb->len < 4) {
        return -EINVAL;
    }

    incoming.throughput = (data[0] << 8) | data[1];
    incoming.packet_size = (data[2] << 8) | data[3];
    len = 4;
    data += 4;

    if (skb->len >= len + 2) {
        incoming.window_size = (data[0] << 8) | data[1];
        len += 2;
        data += 2;
    } else {
        incoming.window_size = X25_DEFAULT_WINDOW_SIZE;
    }

    /* Handle reverse charging */
    if (incoming.reverse_charging) {
        if (!capable(CAP_NET_ADMIN)) {
            return -EPERM;
        }
    }

    /* Negotiate throughput */
    if (incoming.throughput > sk->sk_x25->max_throughput) {
        new->throughput = sk->sk_x25->max_throughput;
    } else {
        new->throughput = incoming.throughput;
    }

    /* Negotiate packet size */
    if (incoming.packet_size > sk->sk_x25->max_packet_size) {
        new->packet_size = sk->sk_x25->max_packet_size;
    } else {
        new->packet_size = incoming.packet_size;
    }

    /* Negotiate window size */
    if (incoming.window_size > sk->sk_x25->max_window_size) {
        new->window_size = sk->sk_x25->max_window_size;
    } else {
        new->window_size = incoming.window_size;
    }

    /* Set DTE facilities based on negotiated values */
    dte->throughput = new->throughput;
    dte->packet_size = new->packet_size;
    dte->window_size = new->window_size;

    if (incoming.reverse_charging)
        dte->flags |= X25_DTE_REVERSE_CHARGING;

    if (incoming.ack_timer > sk->sk_x25->max_ack_timer)
        dte->ack_timer = sk->sk_x25->max_ack_timer;
    else
        dte->ack_timer = incoming.ack_timer;

    if (incoming.window_timer > sk->sk_x25->max_window_timer)
        dte->window_timer = sk->sk_x25->max_window_timer;
    else
        dte->window_timer = incoming.window_timer;

    if (incoming.t1_timer > sk->sk_x25->max_t1_timer)
        dte->t1_timer = sk->sk_x25->max_t1_timer;
    else
        dte->t1_timer = incoming.t1_timer;

    if (incoming.t2_timer > sk->sk_x25->max_t2_timer)
        dte->t2_timer = sk->sk_x25->max_t2_timer;
    else
        dte->t2_timer = incoming.t2_timer;

    if (incoming.t3_timer > sk->sk_x25->max_t3_timer)
        dte->t3_timer = sk->sk_x25->max_t3_timer;
    else
        dte->t3_timer = incoming.t3_timer;

    sk->sk_x25->facilities = *new;

    /* Log debug information */
    net_dbg_ratelimited("X.25 facilities negotiated: throughput %d, packet size %d, window size %d\n",
                        new->throughput, new->packet_size, new->window_size);

    return len;
}

int x25_negotiate_facilities(struct sk_buff *skb, struct sock *sk,
                             struct x25_facilities *new,
                             struct x25_dte_facilities *dte)
{
    struct x25_facilities incoming;
    unsigned int throughput, packet_size, window_size;
    int len;

    memset(&incoming, 0, sizeof(incoming));
    len = x25_parse_facilities(skb, &incoming);
    if (len < 0)
        return len;

    throughput = min(incoming.throughput, sk->x25.throughput);
    packet_size = min(incoming.packet_size, sk->x25.packet_size);
    window_size = min(incoming.window_size, sk->x25.window_size);

    if (incoming.reverse_charge && sk->x25.reverse_charge) {
        new->reverse_charge = 1;
        printk(KERN_DEBUG "X.25: Reverse charging accepted.\n");
    }

    new->throughput = throughput;
    new->packet_size = packet_size;
    new->window_size = window_size;
    dte->throughput = throughput;
    dte->packet_size = packet_size;
    dte->window_size = window_size;

    return len;
}

int x25_negotiate_facilities(struct sk_buff *skb, struct sock *sk, struct x25_facilities *new,
                             struct x25_dte_facilities *dte)
{
    u8 *ptr = skb->data;
    int len = 0;
    int reverse_charging = 0;

    x25_init_facilities(new);
    x25_init_dte_facilities(dte);

    if (skb->len < 2)
        return -EINVAL;

    while (len < skb->len) {
        u8 facility = *ptr++;
        u8 length = *ptr++;

        switch (facility) {
        case X25_FACILITY_REVERSE_CHARGE:
            if (length < 1)
                return -EINVAL;
            reverse_charging = *ptr++;
            break;
        case X25_FACILITY_THROUGHPUT:
            if (length < 1)
                return -EINVAL;
            new->throughput = *ptr++;
            break;
        case X25_FACILITY_PACKET_SIZE:
            if (length < 1)
                return -EINVAL;
            new->packet_size = *ptr++;
            break;
        case X25_FACILITY_WINDOW_SIZE:
            if (length < 1)
                return -EINVAL;
            new->window_size = *ptr++;
            break;
        default:
            ptr += length;
            break;
        }

        len += length + 1;
    }

    if (reverse_charging) {
        new->reverse_charging = 1;
        dte->reverse_charging = 1;
    }

    if (new->throughput > X25_MAX_THROUGHPUT)
        new->throughput = X25_MAX_THROUGHPUT;

    if (new->packet_size > X25_MAX_PACKET_SIZE)
        new->packet_size = X25_MAX_PACKET_SIZE;

    if (new->window_size > X25_MAX_WINDOW_SIZE)
        new->window_size = X25_MAX_WINDOW_SIZE;

    return len;
}
